31	/**
32	 * Simple JavaBean domain object representing an owner.
33	 *
34	 * @author Ken Krebs
35	 * @author Juergen Hoeller
36	 * @author Sam Brannen
37	 * @author Michael Isvy
38	 */
39	@Entity
40	@Table(name = "owners")
41	public class Owner extends Person {
42	    @Column(name = "address")
43	    @NotEmpty
44	    private String address;
45	
46	    @Column(name = "city")
47	    @NotEmpty
48	    private String city;
49	
50	    @Column(name = "telephone")
51	    @NotEmpty
52	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
53	    private String telephone;
54	
55	    @Column(name = "email")
56	    private String email;
57	
58	    @Column(name = "postcode")
59	    private String postcode;
60	
61	    @Column(name = "registration_date")
62	    private LocalDate registrationDate;
63	
64	    @Column(name = "birth_date")
65	    private LocalDate birthDate;
66	
67	    @Column(name = "customer_code")
68	    private String customerCode;
69	
70	    @Column(name = "household_id")
71	    private String householdId;
72	
73	    @Column(name = "namesake_count")
74	    private Integer namesakeCount;
75	
76	    @Column(name = "household_size")
77	    private Integer householdSize;
78	
79	    @Column(name = "membership_number")
80	    private String membershipNumber;
81	
82	    @Column(name = "bulk_signup_warning", nullable = false)
83	    private boolean bulkSignupWarning;
84	
85	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
86	    private Set<Pet> pets;
87	
88	    public String getAddress() {
89	        return this.address;
90	    }
91	
92	    public void setAddress(String address) {
93	        this.address = address;
94	    }
95	
96	    public String getCity() {
97	        return this.city;
98	    }
99	
100	    public void setCity(String city) {
101	        this.city = city;
102	    }
103	
104	    public String getTelephone() {
105	        return this.telephone;
106	    }
107	
108	    public void setTelephone(String telephone) {
109	        this.telephone = telephone;
110	    }
111	
112	    public String getEmail() {
113	        return this.email;
114	    }
115	
116	    public void setEmail(String email) {
117	        this.email = email;
118	    }
119	
120	    /**
121	     * The owner's postcode: a 4-digit code that, when supplied at creation, is validated
122	     * against the city's region and then stored verbatim. Optional, so may be null.
123	     */
124	    public String getPostcode() {
125	        return this.postcode;
126	    }
127	
128	    public void setPostcode(String postcode) {
129	        this.postcode = postcode;
130	    }
131	
132	    public LocalDate getRegistrationDate() {
133	        return this.registrationDate;
134	    }
135	
136	    public void setRegistrationDate(LocalDate registrationDate) {
137	        this.registrationDate = registrationDate;
138	    }
139	
140	    /**
141	     * The owner's date of birth. Optional, so may be null.
142	     */
143	    public LocalDate getBirthDate() {
144	        return this.birthDate;
145	    }
146	
147	    public void setBirthDate(LocalDate birthDate) {
148	        this.birthDate = birthDate;
149	    }
150	
151	    /**
152	     * The owner's age band as at registration: {@code "MINOR"} for under 18,
153	     * {@code "ADULT"} for 18 to 64, or {@code "SENIOR"} for 65 and over, measured from the
154	     * birth date against the registration date. Null when no birth date is recorded.
155	     * Derived from stored state, never persisted.
156	     */
157	    public String getAgeBand() {
158	        if (this.birthDate == null || this.registrationDate == null) {
159	            return null;
160	        }
161	        return AgeBand.of(this.birthDate, this.registrationDate);
162	    }
163	
164	    public String getCustomerCode() {
165	        return this.customerCode;
166	    }
167	
168	    public void setCustomerCode(String customerCode) {
169	        this.customerCode = customerCode;
170	    }
171	
172	    public String getHouseholdId() {
173	        return this.householdId;
174	    }
175	
176	    public void setHouseholdId(String householdId) {
177	        this.householdId = householdId;
178	    }
179	
180	    public Integer getNamesakeCount() {
181	        return this.namesakeCount;
182	    }
183	
184	    public void setNamesakeCount(Integer namesakeCount) {
185	        this.namesakeCount = namesakeCount;
186	    }
187	
188	    public Integer getHouseholdSize() {
189	        return this.householdSize;
190	    }
191	
192	    public void setHouseholdSize(Integer householdSize) {
193	        this.householdSize = householdSize;
194	    }
195	
196	    public String getMembershipNumber() {
197	        return this.membershipNumber;
198	    }
199	
200	    public void setMembershipNumber(String membershipNumber) {
201	        this.membershipNumber = membershipNumber;
202	    }
203	
204	    /**
205	     * Whether this owner was created as part of a bulk signup: {@code true} when more
206	     * than 80 owners had already been registered on this owner's registration date at
207	     * the moment it was created, {@code false} otherwise. Captured at creation.
208	     */
209	    public boolean isBulkSignupWarning() {
210	        return this.bulkSignupWarning;
211	    }
212	
213	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
214	        this.bulkSignupWarning = bulkSignupWarning;
215	    }
216	
217	    /**
218	     * The owner's locality: the canonical region carried in the {@code <REGION>-<HASH8>}
219	     * customer code, i.e. the same region-and-hash identity used everywhere else. That
220	     * region was derived at creation by preferring the postcode range (NSW 2000-2099,
221	     * VIC 3000-3099, QLD 4000-4099), falling back to the fixed city-to-region table
222	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) when the postcode is absent or in no
223	     * known range, or {@code "UNKNOWN"} otherwise. For an owner with no customer code the
224	     * region is derived directly from the stored postcode and city. Derived from stored
225	     * state, never persisted.
226	     */
227	    public String getLocality() {
228	        String region = CustomerCode.regionOf(this.customerCode);
229	        return region != null ? region : CityLocality.forPostcodeOrCity(this.postcode, this.city);
230	    }
231	
232	    /**
233	     * The owner's membership level, from 1 to 3: starts at 1, gains 1 when this owner has
234	     * an email address, and gains 1 when this owner had no namesakes at creation
235	     * ({@code namesakeCount} is 0). Capped at 3 (level 4 is reserved for tenure). Derived
236	     * from stored state, never persisted.
237	     */
238	    public int getMembershipLevel() {
239	        int level = 1;
240	        if (hasEmail()) {
241	            level++;
242	        }
243	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
244	            level++;
245	        }
246	        return Math.min(level, 3);
247	    }
248	
249	    /**
250	     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits of
251	     * the {@code customerCode}. Derived from stored state, never persisted.
252	     */
253	    public int getCheckDigit() {
254	        return LuhnCheckDigit.of(this.customerCode);
255	    }
256	
257	    /**
258	     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is
259	     * present, otherwise {@code "PHONE"}. Derived from stored state, never persisted.
260	     */
261	    public String getContactPreference() {
262	        return hasEmail() ? "EMAIL" : "PHONE";
263	    }
264	
265	    /**
266	     * The owner's identity key: the single value all duplicate detection is expressed
267	     * through, formed as the normalized telephone, the email (or empty when absent) and
268	     * the household id (or empty when none), joined by {@code '|'}. Two owners are
269	     * duplicates only when their whole identity keys are equal, so members of the same
270	     * household with different telephones have different keys and are all allowed. Derived
271	     * from stored state, never persisted.
272	     */
273	    public String getIdentityKey() {
274	        String emailPart = hasEmail() ? this.email : "";
275	        String householdPart = this.householdId == null ? "" : this.householdId;
276	        return this.telephone + "|" + emailPart + "|" + householdPart;
277	    }
278	
279	    private boolean hasEmail() {
280	        return this.email != null && !this.email.isEmpty();
281	    }
282	
283	    protected Set<Pet> getPetsInternal() {
284	        if (this.pets == null) {
285	            this.pets = new HashSet<>();
286	        }
287	        return this.pets;
288	    }
289	
290	    protected void setPetsInternal(Set<Pet> pets) {
291	        this.pets = pets;
292	    }
293	
294	    public List<Pet> getPets() {
295	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
296	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
297	        return Collections.unmodifiableList(sortedPets);
298	    }
299	
300	    public void setPets(List<Pet> pets) {
301	        this.pets = new HashSet<>(pets);
302	    }
303	
304	    public void addPet(Pet pet) {
305	        getPetsInternal().add(pet);
306	        pet.setOwner(this);
307	    }
308	
309	    /**
310	     * Return the Pet with the given name, or null if none found for this Owner.
311	     *
312	     * @param name to test
313	     * @return true if pet name is already in use
314	     */
315	    public Pet getPet(String name) {
316	        return getPet(name, false);
317	    }
318	
319	    /**
320	     * Return the Pet with the given name, or null if none found for this Owner.
321	     *
322	     * @param name to test
323	     * @return true if pet name is already in use
324	     */
325	    public Pet getPet(String name, boolean ignoreNew) {
326	        name = name.toLowerCase();
327	        for (Pet pet : getPetsInternal()) {
328	            if (!ignoreNew || !pet.isNew()) {
329	                String compName = pet.getName();
330	                compName = compName.toLowerCase();
331	                if (compName.equals(name)) {
332	                    return pet;
333	                }
334	            }
335	        }
336	        return null;
337	    }
338	
339	    public Pet getPet(Integer petId) {
340	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
341	    }
342	
343	    @Override
344	    public String toString() {
345	        return new ToStringCreator(this)
346	
347	            .append("id", this.getId())
348	            .append("new", this.isNew())
349	            .append("lastName", this.getLastName())
350	            .append("firstName", this.getFirstName())
351	            .append("address", this.address)
352	            .append("city", this.city)
353	            .append("telephone", this.telephone)
354	            .toString();
355	    }
356	}
