3	/**
4	 * Thrown when a create-owner request's identity key (normalized telephone, email and
5	 * household id, joined by '|') is already used by another owner. Handled by
6	 * {@link DuplicateIdentityKeyExceptionHandler}, which responds 409.
7	 */
8	public class DuplicateIdentityKeyException extends Exception {
9	
10	    private final String identityKey;
11	
12	    public DuplicateIdentityKeyException(String identityKey) {
13	        super("Identity key is already used by another owner: " + identityKey);
14	        this.identityKey = identityKey;
15	    }
16	
17	    public String getIdentityKey() {
18	        return this.identityKey;
19	    }
20	}
