5	import org.springframework.http.HttpStatus;
6	import org.springframework.http.ProblemDetail;
7	import org.springframework.http.ResponseEntity;
8	
9	public class DuplicateIdentityKeyExceptionHandler {
10	
11	    public void handle(@Parameter DuplicateIdentityKeyException ex,
12	            ObjectResponse<ResponseEntity<ProblemDetail>> response) {
13	        ProblemDetail detail = ProblemDetails.build(ex, HttpStatus.CONFLICT,
14	                "An owner with this identity already exists");
15	        response.send(ResponseEntity.status(HttpStatus.CONFLICT).body(detail));
16	    }
17	}
