7	/** soft-match: a new owner that is not a hard duplicate but shares an existing owner's
8	 * lastName and postcode (different telephone) is still created, with 'possibleDuplicate' true and
9	 * 'possibleDuplicateOf' set to the matching owner id. */
10	class AcceptanceTest extends AcceptanceBase {
11	
12		@Test
13		void coreFlagsPossibleDuplicate() throws Exception {
14			String lastName = uniqueLastName();
15			ObjectNode a = withPostcode(ownerNode());
16			a.put("lastName", lastName);
17			int ida = createOwnerOk(a);
18			ObjectNode b = withPostcode(ownerNode()); // same postcode + lastName, unique telephone/address
19			b.put("lastName", lastName);
20			int idb = createOwnerOk(b);
21			getOwner(idb).andExpect(jsonPath("$.possibleDuplicate").value(true))
22					.andExpect(jsonPath("$.possibleDuplicateOf").value(ida));
23		}
24	}
