8	/**
9	 * Rejects a create-owner request whose identity key already belongs to another owner,
10	 * responding 409. The identity key (see {@link Owner#getIdentityKey()}) is the single
11	 * duplicate-detection rule that consolidates the former separate telephone, email and
12	 * household checks: an owner is a duplicate only when its WHOLE key matches an existing
13	 * one, so owners that share a household but differ in telephone or email are all allowed.
14	 * Runs after the telephone and email are normalized ({@link NormalizeOwnerTelephone} /
15	 * {@link NormalizeOwnerEmail}) and the household id is assigned ({@link AssignHouseholdId}),
16	 * so the comparison is between fully derived keys, and before {@link SaveOwner} persists a
17	 * duplicate. Candidates are narrowed by telephone, which every equal key necessarily
18	 * shares.
19	 */
20	public class EnsureUniqueIdentityKey {
21	
22	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
23	            throws DuplicateIdentityKeyException {
24	        String identityKey = owner.getIdentityKey();
25	        for (Owner existing : ownerRepository.findByTelephone(owner.getTelephone())) {
26	            if (identityKey.equals(existing.getIdentityKey())) {
27	                throw new DuplicateIdentityKeyException(identityKey);
28	            }
29	        }
30	    }
31	}
